import request from 'supertest';
import express from 'express';
import { rateLimiter, authLimiter } from '../middleware/rateLimiter';
import { logger } from '../utils/logger';

describe('Rate Limiter Tests', () => {
  let app: express.Application;

  beforeEach(() => {
    app = express();
    // Mock logger to prevent actual file writing during tests
    jest.spyOn(logger, 'warn').mockImplementation(() => logger);
  });

  afterEach(() => {
    jest.clearAllMocks();
  });

  describe('General Rate Limiter', () => {
    beforeEach(() => {
      app.use(rateLimiter);
      app.get('/test', (_req, res) => res.status(200).json({ message: 'success' }));
    });

    it('should allow requests within rate limit', async () => {
      try {
        const requests = Array(5).fill(null).map(() => 
          request(app).get('/test').expect(200)
        );
        
        await Promise.all(requests);
        expect(logger.warn).not.toHaveBeenCalled();
      } catch (error) {
        console.error('Test failed:', error);
        throw error;
      }
    });

    it('should block requests exceeding rate limit', async () => {
      try {
        const requests = Array(101).fill(null).map(() => 
          request(app).get('/test')
        );
        
        const responses = await Promise.all(requests);
        const blockedRequests = responses.filter(r => r.status === 429);
        
        expect(blockedRequests.length).toBeGreaterThan(0);
        expect(logger.warn).toHaveBeenCalled();
      } catch (error) {
        console.error('Test failed:', error);
        throw error;
      }
    });
  });

  describe('Auth Rate Limiter', () => {
    beforeEach(() => {
      app.use('/auth', authLimiter);
      app.post('/auth/login', (_req, res) => res.status(200).json({ message: 'success' }));
    });

    it('should allow requests within auth rate limit', async () => {
      try {
        const requests = Array(3).fill(null).map(() => 
          request(app).post('/auth/login').expect(200)
        );
        
        await Promise.all(requests);
        expect(logger.warn).not.toHaveBeenCalled();
      } catch (error) {
        console.error('Test failed:', error);
        throw error;
      }
    });

    it('should block requests exceeding auth rate limit', async () => {
      try {
        const requests = Array(6).fill(null).map(() => 
          request(app).post('/auth/login')
        );
        
        const responses = await Promise.all(requests);
        const blockedRequests = responses.filter(r => r.status === 429);
        
        expect(blockedRequests.length).toBeGreaterThan(0);
        expect(logger.warn).toHaveBeenCalled();
      } catch (error) {
        console.error('Test failed:', error);
        throw error;
      }
    });

    it('should return correct error message for auth rate limit', async () => {
      try {
        const requests = Array(6).fill(null).map(() => 
          request(app).post('/auth/login')
        );
        
        const responses = await Promise.all(requests);
        const blockedResponse = responses.find(r => r.status === 429);
        
        expect(blockedResponse?.body).toEqual({
          status: 'error',
          message: 'Too many login attempts, please try again after an hour'
        });
      } catch (error) {
        console.error('Test failed:', error);
        throw error;
      }
    });
  });
}); 